import random
from fractions import Fraction as F
random.seed(0)
n = 0
for _ in range(1200):
    k = random.randint(2, 6)
    groups = [[random.randint(100, 999) for _ in range(k)] for _ in range(random.randint(2, 5))]
    avgs = [F(sum(g), k) for g in groups]
    tots = [sum(g) for g in groups]
    assert sorted(range(len(groups)), key=lambda i: avgs[i]) == sorted(range(len(groups)), key=lambda i: tots[i])
    base = random.randint(0, 999)
    for g, a in zip(groups, avgs):
        assert a == base + F(sum(x - base for x in g), k)   # assumed-mean shortcut
    n += 1
# worked example 2024-09-09_1600_Q11
cols = {"C1": [243, 248, 232, 242], "C2": [244, 239, 240, 244], "C3": [244, 236, 235, 230], "C4": [240, 230, 248, 242]}
tot = {c: sum(v) for c, v in cols.items()}
assert tot == {"C1": 965, "C2": 967, "C3": 945, "C4": 960}
dev = {c: sum(x - 240 for x in v) for c, v in cols.items()}
assert dev == {"C1": 5, "C2": 7, "C3": -15, "C4": 0}
best = max(tot, key=tot.get)
assert best == "C2" and sorted(tot.values())[-2] < tot["C2"]
opts = {"A": "C4", "B": "C1", "C": "C2", "D": "C3"}
assert [k for k, c in opts.items() if c == best] == ["C"]
print(f"CASES={n}")
